module x_oracle::oracle_admin;

use pyth::price_info::PriceInfoObject;
use sui::clock::Clock;
use sui::event::emit;

use x_oracle::pyth_adaptor;

public struct PriceDelayToleranceUpdated has drop, copy {
    oracle: ID,
    delay_ms: u64,
    who: address,
    timestamp: u64,
}

public fun migrate(_: &x_oracle::x_oracle::AdminCap, x_oracle: &mut x_oracle::x_oracle::XOracle): u64 {
    x_oracle.migrate()
}

public fun register_pyth_feed<CoinType>(
    _: &x_oracle::x_oracle::AdminCap,
    x_oracle: &mut x_oracle::x_oracle::XOracle,
    pyth_info_object: &PriceInfoObject,
    spot_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
    ema_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
) {
    pyth_adaptor::register_pyth_feed<CoinType>(
        x_oracle.pyth_price_feeds_mut(),
        pyth_info_object,
        spot_confidence_tolerance_bps,
        ema_confidence_tolerance_bps,
    );
}

public fun update_price_delay_tolerance_ms(
    _: &x_oracle::x_oracle::AdminCap,
    x_oracle: &mut x_oracle::x_oracle::XOracle,
    delay_tolerance_ms: u64,
    clock: &Clock,
    ctx: &TxContext,
) {
    x_oracle.update_price_delay_tolerance_ms(delay_tolerance_ms);

    emit(PriceDelayToleranceUpdated {
        oracle: object::id(x_oracle),
        delay_ms: delay_tolerance_ms,
        who: ctx.sender(),
        timestamp: clock.timestamp_ms() / 1000,
    });
}

