   392→   392→
   393→   393→    let obligation = self
   394→   394→        .obligations
   395→   395→        .borrow_mut(obligation_id);
   396→   396→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   397→   397→    let asset_name = type_name::with_defining_ids<CoinType>();
