   691→   691→fun liquidation_inner<MarketType, DebtType, CollateralType>(
   692→   692→    id: &mut UID,
   693→   693→
   694→   694→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   695→   695→    emode_group: &mut EModeGroup,
   696→   696→
   697→   697→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   698→   698→
   699→   699→    obligation: &mut Obligation<MarketType>,
   700→   700→    liquidation_params: &LiquidationParams,
   701→   701→
   702→   702→    mut available_repay_coin: Coin<DebtType>,
   703→   703→
   704→   704→    coin_decimals_registry: &CoinDecimalsRegistry,
   705→   705→    x_oracle: &XOracle,
   706→   706→    clock: &Clock,
   707→   707→
   708→   708→    now: u64,
   709→   709→
   710→   710→    ctx: &mut TxContext,
   711→   711→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   712→   712→    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());
   713→   713→
   714→   714→    let debt_name = type_name::with_defining_ids<DebtType>();
   715→   715→    let collateral_name = type_name::with_defining_ids<CollateralType>();
   716→   716→
   717→   717→    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();
   718→   718→
   719→   719→    // update all assets interest in the obligation
   720→   720→    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);
   721→   721→
   722→   722→    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
   723→   723→        liquidation_params,
   724→   724→        obligation,
   725→   725→        emode_group,
   726→   726→        reserves,
   727→   727→        coin_decimals_registry,
   728→   728→        available_repay_coin.value(),
   729→   729→        x_oracle,
   730→   730→        clock,
   731→   731→    );
   732→   732→
   733→   733→    // calculate how much collateral can be seized first
   734→   734→    let obligation_latest_borrow_amount = obligation.debt(debt_name)
   735→   735→        .unsafe_debt_amount()
   736→   736→        // repay a bit more
   737→   737→        .ceil();
   738→   738→    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
   739→   739→        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
   740→   740→        available_repay_coin.split(refund_amount, ctx)
   741→   741→    } else {
   742→   742→        sui::coin::zero(ctx)
   743→   743→    };
   744→   744→
   745→   745→    // NOTE: disable rate limit
   746→   746→
   747→   747→    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
   748→   748→    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 
   749→   749→
   750→   750→    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
   751→   751→        exchange_rate,
   752→   752→        liquidation_params.liquidation_incentive,
   753→   753→        available_repay_coin.value(),
   754→   754→        emode_group.get_oracle_base_token(),
   755→   755→        x_oracle,
   756→   756→        coin_decimals_registry,
   757→   757→        clock,
   758→   758→    );
   759→   759→
   760→   760→    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
   761→   761→    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
   762→   762→    if (total_ctokens < seized_ctokens) {
   763→   763→        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
   764→   764→            .mul_u64(available_repay_coin.value())
   765→   765→            // repay a bit more
   766→   766→            .ceil();
   767→   767→        let refund = available_repay_coin.value() - expected_repay_amount;
   768→   768→
   769→   769→        refund_coins.join(available_repay_coin.split(refund, ctx));
   770→   770→        seized_ctokens = total_ctokens;
   771→   771→    };
   772→   772→
   773→   773→    // at this stage, even if there is residual, it should be a very small amount, let the protocol consume the residual
   774→   774→    let _residual = obligation.unsafe_repay_debt_only<MarketType, DebtType>(available_repay_coin.value());
   775→   775→
   776→   776→    let ctoken_balance = obligation.withdraw_ctokens<MarketType, CollateralType>(seized_ctokens);
   777→   777→    let ctoken_balance_amount = ctoken_balance.value();
   778→   778→    let refund_balance = collateral_reserve.liquidate_ctokens<MarketType, CollateralType>(
   779→   779→        ctoken_balance.into_coin(ctx),
   780→   780→        liquidation_params.liquidation_revenue_factor,
   781→   781→    );
   782→   782→
   783→   783→    let obligation_new_borrow_amount = if (!obligation.has_debt(debt_name)) { float::zero() } else { obligation.debt(debt_name).unsafe_debt_amount() };
   784→   784→    emode_group.update_asset_borrow(debt_name, obligation_old_borrow_amount, obligation_new_borrow_amount);
   785→   785→
   786→   786→    let debt_reserve = reserves.load_mut_by_type(debt_name);
   787→   787→    debt_reserve.repay_amount<MarketType, DebtType>(available_repay_coin);
   788→   788→
   789→   789→    try_stop_borrow_deleverage<MarketType, DebtType>(id, obligation.emode_group(), emode_group, debt_name);
   790→   790→    try_stop_collateral_deleverage<MarketType, CollateralType>(id, reserves, collateral_name);
   791→   791→
   792→   792→    (refund_balance.into_coin(ctx), refund_coins, ctoken_balance_amount)
   793→   793→}
