   795→   795→public(package) fun borrow_flash_loan<MarketType, CoinType>(
   796→   796→    self: &mut Market<MarketType>,
   797→   797→    emode_group: u8,
   798→   798→    amount: u64,
   799→   799→    ctx: &mut TxContext,
   800→   800→): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
   801→   801→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   802→   802→
   803→   803→    assert!(!asset.flash_loan_paused(), error::flash_loan_paused_for_asset());
   804→   804→    assert!(!asset.flash_loan_ongoing(), error::flash_loan_ongoing());
   805→   805→
   806→   806→    asset.flash_loan_triggered<MarketType>();
   807→   807→
   808→   808→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   809→   809→
   810→   810→    let emode = self.emode_group_registry.borrow_emode_group(emode_group).borrow_emode(type_name::with_defining_ids<CoinType>());
   811→   811→    let flash_loan_fee_rate = emode.flash_loan().fee_rate();
   812→   812→
   813→   813→    let fee = flash_loan_fee_rate.int_mul(amount);
   814→   814→    assert!(fee != 0, error::reserve_flash_loan_fee_too_small());
   815→   815→
   816→   816→    let (balance, inner) = reserve.borrow_flash_loan(amount);
   817→   817→    (balance.into_coin(ctx), FlashLoan<MarketType, CoinType> { inner, fee })
   818→   818→}
