   820→   820→public(package) fun repay_flash_loan<MarketType, CoinType>(
   821→   821→    self: &mut Market<MarketType>,
   822→   822→
   823→   823→    mut coin: Coin<CoinType>,
   824→   824→    loan: FlashLoan<MarketType, CoinType>,
   825→   825→
   826→   826→    referral: &mut protocol::referral::Referral,
   827→   827→    mut maybe_referral_code: Option<String>,
   828→   828→
   829→   829→    ctx: &mut TxContext
   830→   830→) {
   831→   831→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   832→   832→
   833→   833→    assert!(asset.flash_loan_ongoing(), error::flash_loan_not_ongoing());
   834→   834→    asset.flash_loan_finished<MarketType>();
   835→   835→
   836→   836→    let FlashLoan { inner, fee } = loan;
   837→   837→    assert!(coin.value() == inner.amount() + fee, error::reserve_flash_loan_not_paid_enough());
   838→   838→
   839→   839→    let mut fee_coin = coin.split(fee, ctx);
   840→   840→
   841→   841→    if (maybe_referral_code.is_some()) {
   842→   842→        let referral_code = maybe_referral_code.extract();
   843→   843→        fee_coin = referral.track_flash_loan_usage(
   844→   844→            fee_coin,
   845→   845→            referral_code,
   846→   846→            ctx.sender(),
   847→   847→            ctx,
   848→   848→        );
   849→   849→        
   850→   850→        // no free ride after rebate
   851→   851→        assert!(fee_coin.value() != 0, error::reserve_flash_loan_fee_too_small());
   852→   852→    };
   853→   853→
   854→   854→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   855→   855→    reserve.repay_flash_loan(inner, coin, fee_coin);
   856→   856→}
