  1085→  1085→// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
  1086→  1086→fun collaterals_usd_for_liquidation<MarketType>(
  1087→  1087→    emode_group: &EModeGroup,
  1088→  1088→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1089→  1089→
  1090→  1090→    obligation: &Obligation<MarketType>,
  1091→  1091→
  1092→  1092→    coin_decimals_registry: &CoinDecimalsRegistry,
  1093→  1093→    x_oracle: &XOracle,
  1094→  1094→    clock: &Clock,
  1095→  1095→): (Decimal, Decimal) {
  1096→  1096→    let mut total_weighted_usd = float::zero();
  1097→  1097→    let mut total_collateral_usd = float::zero();
  1098→  1098→
  1099→  1099→    let mut deposit_types = obligation.deposit_types();
  1100→  1100→    let oracle_base_token = emode_group.get_oracle_base_token();
  1101→  1101→
  1102→  1102→    while (!deposit_types.is_empty()) {
  1103→  1103→        let deposit_type = deposit_types.pop_back();
  1104→  1104→
  1105→  1105→        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();
  1106→  1106→        // cannot be collateral, ignore
